using Microsoft.EntityFrameworkCore;
using PersonalFinance.Api.Domain;
namespace PersonalFinance.Api.Application;
public sealed record ConcertPricePoint(DateOnly Date,string Amount,string Source);
public sealed record ConcertCollection(string Name,string Currency,string Kind,string Edition,string Size,string Color,string Number,string Location,string State,string? PurchaseId,string? ItemId,string? PrepaymentId,string ExpectedPrice,string? SaleTransactionId,string? ReturnTransactionId,ConcertPricePoint[] Prices,string Note,[property:System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] int? Quantity=null,[property:System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] string[]? AdditionalSaleIds=null,[property:System.Text.Json.Serialization.JsonIgnore(Condition=System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull)] string[]? AdditionalReturnIds=null);
public sealed partial class FinanceService {
 const string ConcertCollectionKind="ConcertCollection";
 static IEnumerable<string> CollectionIncomeIds(ConcertCollection c)=>(c.SaleTransactionId==null?Array.Empty<string>():new[]{c.SaleTransactionId}).Concat(c.AdditionalSaleIds??[]);
 static IEnumerable<string> CollectionExpenseIds(ConcertCollection c)=>(c.ReturnTransactionId==null?Array.Empty<string>():new[]{c.ReturnTransactionId}).Concat(c.AdditionalReturnIds??[]);
 async Task<ConcertCollection[]> CollectionInputs(string user)=>(await InterestDocs(user,ConcertCollectionKind)).Select(InterestRead<ConcertCollection>).ToArray();
 public async Task<object> ConcertCollectionPurchase(string user,string id){await RequireConcerts(user);var d=await Document(user,id,InterestPurchaseKind);return new{d.Id,version=d.Version.ToString(),input=InterestRead<InterestPurchase>(d)};}
 async Task ValidateCollectionSourceExclusion(string user,IEnumerable<string> incomeIds,IEnumerable<string> expenseIds) {
  var collections=await CollectionInputs(user);Require(!collections.Any(c=>CollectionIncomeIds(c).Any(incomeIds.Contains) || CollectionExpenseIds(c).Any(expenseIds.Contains)),"资金来源已完整关联收藏出售/返款，不能重复分配到其他用途");
 }
 public async Task<object> ConcertCollections(string user) {
  await RequireConcerts(user);var docs=await InterestDocs(user,ConcertCollectionKind);var result=new List<object>();var scenes=(await ConcertDocs(user)).Select(ConcertRead).ToArray();var music=(await InterestDocs(user,InterestPurchaseKind)).Select(InterestRead<InterestPurchase>).ToArray();
  foreach(var doc in docs){var item=InterestRead<ConcertCollection>(doc);decimal cost=0,sale=0,returned=0,deposit=0;var costVerified=false;var warnings=new List<string>();
   if(item.PurchaseId!=null){var purchase=InterestRead<InterestPurchase>(await Document(user,item.PurchaseId,InterestPurchaseKind));var original=purchase.Items.SingleOrDefault(i=>i.Id==item.ItemId);var tx=await db.Transactions.AsNoTracking().SingleOrDefaultAsync(t=>t.UserId==user && t.Id==purchase.TransactionId);if(original!=null && tx?.Status=="Confirmed" && tx.Type=="Expense" && tx.Currency==item.Currency && tx.BusinessId==null && tx.OccurredAt<=DateTimeOffset.UtcNow && ConcertExpenseUse(tx.Id,scenes,music)<=tx.Amount && purchase.State=="Purchased"){cost=Money(original.Paid);costVerified=true;}else warnings.Add("原购买来源已变化，请核对实际成本");}
   if(item.PrepaymentId!=null){var prepaid=await db.Set<PrepaymentContract>().AsNoTracking().SingleOrDefaultAsync(p=>p.UserId==user && p.Id==item.PrepaymentId);if(prepaid!=null)deposit=prepaid.Amount-prepaid.RefundedAmount-prepaid.WrittenOffAmount;else warnings.Add("原预付款合同已变化");}
   foreach(var pair in CollectionIncomeIds(item).Select(linkId=>(Id:linkId,Income:true)).Concat(CollectionExpenseIds(item).Select(linkId=>(Id:linkId,Income:false))))if(pair.Id!=null){var tx=await db.Transactions.AsNoTracking().SingleOrDefaultAsync(t=>t.UserId==user && t.Id==pair.Id);if(tx?.Status=="Confirmed" && tx.Type==(pair.Income?"Income":"Expense") && tx.BusinessId==null && tx.Currency==item.Currency && tx.OccurredAt<=DateTimeOffset.UtcNow){if(pair.Income)sale+=tx.Amount;else returned+=tx.Amount;}else warnings.Add("出售或返款来源已变化");}
   var duplicates=docs.Count(d=>{var other=InterestRead<ConcertCollection>(d);return d.Id!=doc.Id && other.State is "Held" or "Preordered" && string.Equals(other.Name.Trim(),item.Name.Trim(),StringComparison.OrdinalIgnoreCase) && other.Edition==item.Edition && other.Size==item.Size && other.Color==item.Color;});
   result.Add(new{doc.Id,version=doc.Version.ToString(),input=item,report=new{cost=costVerified?M(cost):null,prepaid=M(deposit),estimatedBalance=M(Math.Max(0,Money(item.ExpectedPrice)-deposit)),sale=M(sale),returned=M(returned),netSale=M(sale-returned),duplicates,warnings,rule="原购买成本、原预付款与出售收支分别显示；预付款不再次加作成本。预计尾款及价格历史不作为资产/负债，不自动记账，退款净成本以原购买档案为准。"}});
  }return result;
 }
 public async Task<object> SaveConcertCollection(string user,string? id,ConcertCollection item,string? version) {
  await RequireConcerts(user);if(id!=null){var prior=InterestRead<ConcertCollection>(await Document(user,id,ConcertCollectionKind));item=item with{AdditionalSaleIds=item.AdditionalSaleIds??prior.AdditionalSaleIds,AdditionalReturnIds=item.AdditionalReturnIds??prior.AdditionalReturnIds};}ConcertIds(CollectionIncomeIds(item));ConcertIds(CollectionExpenseIds(item));Require((item.Quantity??1) is >=1 and <=10000,"收藏数量须为1到10000");ConcertText(item.Name,200,true);foreach(var text in new[]{item.Kind,item.Edition,item.Size,item.Color,item.Number,item.Location})ConcertText(text,200);ConcertText(item.Note,2000);Require(CurrencyDefinitions.Supports(item.Currency) && Money(item.ExpectedPrice)>=0 && item.State is "Wishlist" or "Preordered" or "Held" or "Gifted" or "Sold" or "Returned","收藏币种、预计价格或状态无效");Require(item.Prices.Length<=200,"价格历史最多200条");foreach(var price in item.Prices){Require(price.Date.Year>=1900 && price.Date<=DateOnly.FromDateTime(DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(8)).DateTime) && Money(price.Amount)>=0,"价格历史日期或金额无效");ConcertText(price.Source,500,true);}
  Require((item.PurchaseId==null)==(item.ItemId==null),"购买档案与商品须同时关联或解除");if(item.PurchaseId!=null){var purchase=InterestRead<InterestPurchase>(await Document(user,item.PurchaseId,InterestPurchaseKind));Require(purchase.Currency==item.Currency && purchase.Items.Any(i=>i.Id==item.ItemId && i.Quantity==(item.Quantity??1)),"购买商品不属于本人同币种档案");}
  if(item.PrepaymentId!=null)Require(await db.Set<PrepaymentContract>().AnyAsync(p=>p.UserId==user && p.Id==item.PrepaymentId && p.Currency==item.Currency),"请选择本人同币种原预付款合同");
  var all=(await InterestDocs(user,ConcertCollectionKind)).Where(d=>d.Id!=id).Select(InterestRead<ConcertCollection>).ToArray();Require(item.PurchaseId==null || !all.Any(c=>c.PurchaseId==item.PurchaseId && c.ItemId==item.ItemId),"同一购买商品已有收藏档案，请编辑原档案");
  Require(item.PrepaymentId==null || !all.Any(c=>c.PrepaymentId==item.PrepaymentId),"同一整笔预付款合同已有收藏关联，请在原档案核对，不能重复作为定金");var tripSources=(await InterestDocs(user,ConcertTripKind)).Select(InterestRead<ConcertTrip>).SelectMany(t=>t.Expenses).Select(e=>e.TransactionId).ToHashSet();
  var scenes=(await ConcertDocs(user)).Select(ConcertRead).ToArray();var music=(await InterestDocs(user,InterestPurchaseKind)).Select(InterestRead<InterestPurchase>).ToArray();decimal sale=0,returned=0;
  foreach(var pair in CollectionIncomeIds(item).Select(linkId=>(Id:linkId,Income:true)).Concat(CollectionExpenseIds(item).Select(linkId=>(Id:linkId,Income:false))))if(pair.Id!=null){Require(!all.Any(c=>CollectionIncomeIds(c).Concat(CollectionExpenseIds(c)).Contains(pair.Id)),"同一资金流水只能完整关联一个收藏出售档案");var tx=await db.Transactions.AsNoTracking().SingleOrDefaultAsync(t=>t.UserId==user && t.Id==pair.Id);Require(tx!=null && tx.Type==(pair.Income?"Income":"Expense") && tx.BusinessId==null && tx.Status=="Confirmed" && tx.Currency==item.Currency && tx.OccurredAt<=DateTimeOffset.UtcNow,"出售/返款须明确关联本人已发生已确认同币种普通流水");Require(pair.Income?!ConcertIncomeLinks(scenes).Any(p=>p.TransactionId==pair.Id):ConcertExpenseUse(pair.Id!,scenes,music)==0 && !tripSources.Contains(pair.Id!),"该来源已分配到场次、转让、理赔或商品，不能重复使用");if(pair.Income)sale+=tx!.Amount;else returned+=tx!.Amount;}
  Require(returned<=sale && (!CollectionExpenseIds(item).Any() || CollectionIncomeIds(item).Any()),"实际返款不能超过实收出售款");Require(item.State!="Sold" || CollectionIncomeIds(item).Any(),"已出售须关联实际收入；本表不会自动记账");Require(item.State=="Sold" || sale==returned,"非出售状态须先核对出售收支抵平，原记账不自动冲销");return await SaveInterestDocument(user,ConcertCollectionKind,id,item,version);
 }
}
